+
+      .required-marker {
+        color: var(--danger);
+        font-weight: 900;
+      }
+
+      .helper-text,
+      .error-text {
+        grid-column: 2;
+        margin: 0;
+        font-size: 0.92rem;
+        line-height: 1.5;
+      }
+
+      .helper-text {
+        color: var(--muted);
+      }
+
+      .error-text {
+        color: var(--danger);
+        font-weight: 700;
+      }
+
+      .error-text[hidden] {
