<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Terms Consent</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --panel: #ffffff;
        --text: #172033;
        --muted: #5f6f89;
        --border: #d8dfeb;
        --primary: #2457d6;
        --primary-hover: #1d46ad;
        --danger: #b42318;
        --ring: #7da0ff;
        --shadow: 0 24px 60px rgba(23, 32, 51, 0.14);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(36, 87, 214, 0.16), transparent 34rem),
          linear-gradient(135deg, #f8fbff 0%, var(--bg) 100%);
      }

      a {
        color: var(--primary);
        font-weight: 700;
        text-underline-offset: 0.18em;
      }

      a:hover {
        color: var(--primary-hover);
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid var(--ring);
        outline-offset: 3px;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        color: #ffffff;
        background: var(--text);
        border-radius: 999px;
        transform: translateY(-150%);
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem;
      }

      .consent-card {
        width: min(100%, 34rem);
        padding: clamp(1.5rem, 4vw, 2.5rem);
        background: rgba(255, 255, 255, 0.92);
        border: 1px solid rgba(216, 223, 235, 0.9);
        border-radius: 1.5rem;
        box-shadow: var(--shadow);
        backdrop-filter: blur(16px);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--primary);
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.1em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 7vw, 3.25rem);
        line-height: 1.04;
        letter-spacing: -0.055em;
      }

      .intro {
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.35rem 0.85rem;
        padding: 1rem;
        background: #f9fbff;
        border: 1px solid var(--border);
        border-radius: 1rem;
      }

      .form-field input {
        width: 1.25rem;
        height: 1.25rem;
        margin: 0.15rem 0 0;
        accent-color: var(--primary);
        cursor: pointer;
      }

      .checkbox-label {
        color: var(--text);
        font-weight: 700;
        line-height: 1.45;
        cursor: pointer;
      }

      .required-marker {
        color: var(--danger);
        font-weight: 900;
      }

      .helper-text,
      .error-text {
        grid-column: 2;
        margin: 0;
        font-size: 0.92rem;
        line-height: 1.5;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-text {
        color: var(--danger);
        font-weight: 700;
      }

      .error-text[hidden] {
        display: none;
      }

      .form-field.has-error {
        border-color: var(--danger);
        background: #fff8f7;
      }

      .submit-button {
        min-height: 3rem;
        padding: 0.85rem 1.1rem;
        color: #ffffff;
        background: var(--primary);
        border: 0;
        border-radius: 999px;
        box-shadow: 0 12px 24px rgba(36, 87, 214, 0.24);
        cursor: pointer;
        font: inherit;
        font-weight: 800;
      }

      .submit-button:hover {
        background: var(--primary-hover);
      }

      .status-message {
        min-height: 1.5rem;
        margin: 0;
        color: #237a45;
        font-weight: 700;
      }

      @media (max-width: 28rem) {
        .page-shell {
          padding: 1rem;
        }

        .consent-card {
          border-radius: 1.1rem;
        }

        .form-field {
          grid-template-columns: auto minmax(0, 1fr);
          padding: 0.9rem;
        }
      }

      @media (forced-colors: active) {
        .consent-card,
        .form-field,
        .submit-button {
          border: 1px solid CanvasText;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content" class="page-shell">
      <div id="app"></div>
    </main>

    <script>
      const components = {
        ConsentField() {
          return `
            <div class="form-field" id="consent-field">
              <input
                id="terms-consent"
                name="terms-consent"
                type="checkbox"
                required
                aria-describedby="terms-helper terms-error"
              >
              <label class="checkbox-label" for="terms-consent">
                I agree to the <a href="#" aria-label="terms of use">terms of use</a>
                <span class="required-marker" aria-hidden="true">*</span>
                <span class="visually-hidden">required</span>
              </label>
              <p class="helper-text" id="terms-helper">Required to create and manage your account.</p>
              <p class="error-text" id="terms-error" hidden>Error: You must agree to the terms of use before continuing.</p>
            </div>
          `;
        },
        ConsentForm() {
          return `
            <section class="consent-card" aria-labelledby="page-title">
              <p class="eyebrow">Account setup</p>
              <h1 id="page-title">Review and continue</h1>
              <p class="intro">Confirm your consent to proceed with a secure, product-ready experience.</p>
              <form id="consent-form" novalidate>
                ${this.ConsentField()}
                <button class="submit-button" type="submit">Agree and continue</button>
                <p class="status-message" id="form-status" aria-live="polite"></p>
              </form>
            </section>
          `;
        },
        App() {
          return this.ConsentForm();
        }
      };

      document.getElementById("app").innerHTML = components.App();

      const form = document.getElementById("consent-form");
      const field = document.getElementById("consent-field");
      const checkbox = document.getElementById("terms-consent");
      const error = document.getElementById("terms-error");
      const status = document.getElementById("form-status");

      function setConsentError(isInvalid) {
        checkbox.setAttribute("aria-invalid", String(isInvalid));
        error.hidden = !isInvalid;
        field.classList.toggle("has-error", isInvalid);
      }

      checkbox.addEventListener("change", () => {
        setConsentError(!checkbox.checked);
        if (checkbox.checked) {
          status.textContent = "";
        }
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!checkbox.checked) {
          setConsentError(true);
          status.textContent = "";
          checkbox.focus();
          return;
        }

        setConsentError(false);
        status.textContent = "Thanks. Your consent has been recorded.";
      });
    </script>
  </body>
</html>
