         display: none;
       }

       .form-field.has-error {
         border-color: var(--danger);
         background: #fff8f7;
       }

       .submit-button {
         min-height: 3rem;
         padding: 0.85rem 1.1rem;
         color: #ffffff;
         background: var(--primary);
         border: 0;
         border-radius: 999px;
         box-shadow: 0 12px 24px rgba(36, 87, 214, 0.24);
         cursor: pointer;
         font: inherit;
         font-weight: 800;
       }

       .submit-button:hover {
         background: var(--primary-hover);
       }

       .status-message {
         min-height: 1.5rem;
         margin: 0;
         color: #237a45;
         font-weight: 700;
       }

       @media (max-width: 28rem) {
         .page-shell {
           padding: 1rem;
         }

         .consent-card {
           border-radius: 1.1rem;
