               <p class="helper-text" id="terms-helper">Required to create and manage your account.</p>
               <p class="error-text" id="terms-error" hidden>Error: You must agree to the terms of use before continuing.</p>
             </div>
           `;
         },
         ConsentForm() {
           return `
             <section class="consent-card" aria-labelledby="page-title">
               <p class="eyebrow">Account setup</p>
               <h1 id="page-title">Review and continue</h1>
               <p class="intro">Confirm your consent to proceed with a secure, product-ready experience.</p>
