      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 7vw, 3.25rem);
        line-height: 1.04;
        letter-spacing: -0.055em;
      }

      .intro {
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.35rem 0.85rem;
        padding: 1rem;
        background: #f9fbff;
        border: 1px solid var(--border);
        border-radius: 1rem;
      }

      .form-field input {
        width: 1.25rem;
        height: 1.25rem;
        margin: 0.15rem 0 0;
        accent-color: var(--primary);
        cursor: pointer;
      }

      .checkbox-label {
        color: var(--text);
        font-weight: 700;
        line-height: 1.45;
        cursor: pointer;
      }

      .required-marker {
        color: var(--danger);
        font-weight: 900;
      }

      .helper-text,
      .error-text {
        grid-column: 2;
        margin: 0;
        font-size: 0.92rem;
        line-height: 1.5;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-text {
        color: var(--danger);
        font-weight: 700;
      }

      .error-text[hidden] {
        display: none;
      }

      .form-field.has-error {
        border-color: var(--danger);
        background: #fff8f7;
      }

      .submit-button {
        min-height: 3rem;
        padding: 0.85rem 1.1rem;
        color: #ffffff;
        background: var(--primary);
        border: 0;
        border-radius: 999px;
        box-shadow: 0 12px 24px rgba(36, 87, 214, 0.24);
        cursor: pointer;
        font: inherit;
        font-weight: 800;
      }

      .submit-button:hover {
        background: var(--primary-hover);
      }

      .status-message {
        min-height: 1.5rem;
        margin: 0;
        color: #237a45;
        font-weight: 700;
      }

      @media (max-width: 28rem) {
        .page-shell {
          padding: 1rem;
        }

        .consent-card {
          border-radius: 1.1rem;
        }

        .form-field {
          grid-template-columns: auto minmax(0, 1fr);
          padding: 0.9rem;
        }
      }

      @media (forced-colors: active) {
        .consent-card,
        .form-field,
        .submit-button {
          border: 1px solid CanvasText;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content" class="page-shell">
      <div id="app"></div>
    </main>

    <script>
      const components = {
        ConsentField() {
          return `
            <div class="form-field" id="consent-field">
              <input
                id="terms-consent"
                name="terms-consent"
                type="checkbox"
                required
                aria-describedby="terms-helper"
              >
              <label class="checkbox-label" for="terms-consent">
                I agree to the terms of use
                <span class="required-marker" aria-hidden="true">*</span>
                <span class="visually-hidden">required</span>
              </label>
              <p class="helper-text" id="terms-helper">Required to create and manage your account.</p>
              <p class="error-text" id="terms-error" hidden>Error: You must agree to the terms of use before continuing.</p>
            </div>
          `;
        },
        ConsentForm() {
          return `
            <section class="consent-card" aria-labelledby="page-title">
              <p class="eyebrow">Account setup</p>
              <h1 id="page-title">Review and continue</h1>
              <p class="intro">Confirm your consent to proceed with a secure, product-ready experience.</p>
              <form id="consent-form" novalidate>
                ${this.ConsentField()}
                <button class="submit-button" type="submit">Agree and continue</button>
                <p class="status-message" id="form-status" aria-live="polite"></p>
              </form>
            </section>
          `;
        },
        App() {
          return this.ConsentForm();
        }
      };

      document.getElementById("app").innerHTML = components.App();

      const form = document.getElementById("consent-form");
      const field = document.getElementById("consent-field");
      const checkbox = document.getElementById("terms-consent");
      const error = document.getElementById("terms-error");
      const status = document.getElementById("form-status");

      function setConsentError(isInvalid) {
        if (isInvalid) {
          checkbox.setAttribute("aria-invalid", "true");
          checkbox.setAttribute("aria-describedby", "terms-helper terms-error");
        } else {
          checkbox.removeAttribute("aria-invalid");
          checkbox.setAttribute("aria-describedby", "terms-helper");
        }
        error.hidden = !isInvalid;
        field.classList.toggle("has-error", isInvalid);
      }

      checkbox.addEventListener("change", () => {
        setConsentError(!checkbox.checked);
        if (checkbox.checked) {
          status.textContent = "";
        }
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!checkbox.checked) {
          setConsentError(true);
          status.textContent = "";
          checkbox.focus();
          return;
        }

        setConsentError(false);
        status.textContent = "Thanks. Your consent has been recorded.";
      });
    </script>
  </body>
</html>
